<script setup lang="ts">
const auth = useAuth(), api = useApi()
interface Task { id: string; name: string; cron_expression: string; timezone: string; job_type: string; enabled: boolean; next_run_at: string; last_run_at: string | null }
const tasks = ref<Task[]>([]), busy = ref(false), error = ref(''), stats = ref<Record<string, unknown>>({})
async function load() { busy.value = true; error.value = ''; try { const data = await api.get<{data:Task[];stats:Record<string,unknown>}>('/admin/scheduler'); tasks.value = data.data; stats.value = data.stats } catch (e) { error.value = apiError(e).message } finally { busy.value = false } }
onMounted(() => { if (auth.can('admin.scheduler.read')) void load() })
</script>
<template><div><h1>Планировщик</h1><p class="page-subtitle">Зарегистрированные задания PostgreSQL scheduler. Управление расписанием выполняется через CLI.</p><UiAlert v-if="!auth.can('admin.scheduler.read')" tone="info" message="Недостаточно прав." /><template v-else><div class="toolbar"><span class="muted">Статистика: {{ JSON.stringify(stats) }}</span><button class="btn" :disabled="busy" @click="load">Обновить</button></div><UiAlert :message="error" /><section v-if="tasks.length" class="panel table-wrap"><table class="table"><thead><tr><th>Задача</th><th>Cron / TZ</th><th>Тип</th><th>Статус</th><th>Следующее выполнение</th></tr></thead><tbody><tr v-for="task in tasks" :key="task.id"><td>{{ task.name }}</td><td class="mono small">{{ task.cron_expression }} / {{ task.timezone }}</td><td>{{ task.job_type }}</td><td><span :class="['tag', task.enabled ? 'good' : 'bad']">{{ task.enabled ? 'Включено' : 'Отключено' }}</span></td><td>{{ task.next_run_at }}</td></tr></tbody></table></section><div v-else-if="!busy" class="empty">Нет зарегистрированных расписаний.</div></template></div></template>
